'use strict';

module.exports = {
  ignores: [ 'node_modules/', 'LICENSE.md' ],

  globs: [ '**/*.md' ],

  config: {
    // Enable all markdownlint rules
    default: true,

    // Set list indent level to 4 which mkdocs / Python-Markdown requires
    MD007: { indent: 4 },

    // Enable line length check but exclude tables and code blocks
    MD013: {
      line_length: 120,
      tables: false,
      code_blocks: false,
    },

    // Allow multiple subheadings with the same content
    // across different section (#1 ##A ##B #2 ##A ##B)
    MD024: {
      siblings_only: true,
    },

    // Set Ordered list item prefix to "ordered" (use 1. 2. 3. not 1. 1. 1.)
    MD029: { style: 'ordered' },

    // Allow inline HTML
    MD033: false,
  },
};

{ "types": [ { "type": "feat", "section": "Features" }, { "type": "fix", "section": "Fixes" }, { "type": "chore", "section": "Chores" }, { "type": "chore(deps)", "section": "Dependency updates" }, { "type": "docs", "section": "Documentation" }, { "type": "style", "section": "Styling" }, { "type": "refactor", "section": "Refactors" }, { "type": "perf", "section": "Performance" }, { "type": "test", "section": "Testing" } ], "header": "<!-- markdownlint-disable MD013 -->
# Changelog

All notable changes to this project will be documented in this file.", "releaseCommitMessageFormat": "chore(release): Release version {{currentTag}} of the npm package" }

module.exports = {
  extends: [ '@commitlint/config-conventional' ],
  rules: {
    'subject-case': [
      2,
      'never',
      [ 'start-case', 'kebab-case', 'snake-case' ],
    ],
  },
};

import opinionated from 'opinionated-eslint-config';

export default opinionated().append({
  // Don't want to lint test assets
  ignores: [ 'test/assets/*', 'componentsjs-error-state.json' ],
});

const os = require('node:os');
const v8 = require('node:v8');

// Several parts inspired by https://github.com/renovatebot/renovate/blob/main/package.json

const ci = Boolean(process.env.CI);

const cpus = os.cpus();
const mem = os.totalmem();
const stats = v8.getHeapStatistics();

if (ci) {
  process.stderr.write(`Host stats:
  Cpus:      ${cpus.length}
  Memory:    ${(mem / 1024 / 1024 / 1024).toFixed(2)} GB
  HeapLimit: ${(stats.heap_size_limit / 1024 / 1024 / 1024).toFixed(2)} GB
`);
}

// See also https://github.com/jestjs/jest/issues/11956
function jestGithubRunnerSpecs() {
  return {
    maxWorkers: cpus.length,
    workerIdleMemoryLimit: '1500MB',
  };
}

// ESM libraries that need to be transformed so Jest can handle them
const esModules = [
  'oidc-provider',
  'nanoid',
  'got',
  'quick-lru',
  '@sindresorhus/is',
  'p-cancelable',
  '@szmarczak/http-timer',
  'cacheable-request',
  'normalize-url',
  'responselike',
  'lowercase-keys',
  'mimic-response',
  'form-data-encoder',
  'cacheable-lookup',
];

module.exports = {
  transform: {
    '^.+\\.ts$': [ 'ts-jest', {
      tsconfig: '<rootDir>/test/tsconfig.json',
      diagnostics: false,
      isolatedModules: true,
    }],
    // This transformer converts ESM packages to CJS
    '^.+node_modules.+\\.js$': 'jest-esm-transformer-2',
  },
  // By default, node_modules are not transformed, but we want to transform the ESM packages
  transformIgnorePatterns: [ `/node_modules/(?!(${esModules.join('|')})/)` ],
  testRegex: '/test/(unit|integration)/.*\\.test\\.ts$',
  moduleFileExtensions: [
    'ts',
    'js',
  ],
  testEnvironment: 'node',
  globalSetup: '<rootDir>/test/util/SetupTests.ts',
  globalTeardown: '<rootDir>/test/util/TeardownTests.ts',
  setupFilesAfterEnv: [ 'jest-rdf' ],
  collectCoverage: false,
  // See https://github.com/matthieubosquet/ts-dpop/issues/13
  moduleNameMapper: {
    '^jose/(.*)$': '<rootDir>/node_modules/jose/dist/node/cjs/$1',
  },
  // Slower machines had problems calling the WebSocket integration callbacks on time
  testTimeout: 90000,

  reporters: ci ? [ 'default', 'github-actions' ] : [ 'default' ],
  ...ci && jestGithubRunnerSpecs(),
};

const jestConfig = require('./jest.config');

module.exports = {
  ...jestConfig,
  collectCoverage: true,
  coverageReporters: [ 'text', 'lcov' ],
  coveragePathIgnorePatterns: [
    '/dist/',
    '/node_modules/',
    '/test/',
  ],
  coverageThreshold: {
    './src': {
      branches: 100,
      functions: 100,
      lines: 100,
      statements: 100,
    },
  },
};
